class Solution {
public:
    int wateringPlants(vector<int>& plants, int capacity) {
        long long steps = 0;
        int water = capacity;
        int pos = -1;
        int n = plants.size();
        for (int i = 0; i < n; i++) {
            if (water >= plants[i]) {
                steps += (i - pos);
                water -= plants[i];
                pos = i;
            } else {
                steps += (pos + 1);
                steps += (i + 1);
                water = capacity - plants[i];
                pos = i;
            }
        }
        return (int)steps;
    }
};
